  "sim.perfume-lab.desc": "روغن‌های اسانسی و ترکیبات آروماتیک را ترکیب کن تا عطرهای اختصاصی بسازی و به معیارهای کیفیت برسـی.",
  "sim.detergent-lab.title": "آزمایشگاه شوینده",
  "sim.detergent-lab.desc": "فرمول‌سازی محصولات شوینده — تعادل بین سورفکتانت‌ها، پرکننده‌ها و آزمون‌های عملکرد در چارچوب بودجه.",
  "sim.skin-care-lab.title": "آزمایشگاه مراقبت از پوست",
  "sim.skin-care-lab.desc": "فرمول‌های محصولات آرایشی را توسعه و آزمایش کن و استانداردهای ایمنی و اهداف اثربخشی را رعایت کن.",
  "sim.woodworking.title": "کارگاه نجاری",
  "sim.woodworking.desc": "یک کارگاه نجاری سفارشی اجرا کن: برنامه‌ریزی کارها، مدیریت مواد و تحویل مبلمان به‌موقع و مطابق بودجه.",
  "sim.aluminum-glazing.title": "آلومینیوم و شیشه",
  "sim.aluminum-glazing.desc": "یک کسب‌وکار ساخت آلومینیوم و نصب شیشه را از تهیه پیش‌نویس تا تکمیل محل مدیریت کن.",
  "sim.global-kitchen.title": "آشپزخانه جهانی",
  "sim.global-kitchen.desc": "آشپزخانه رستوران را مدیریت کن: منوها، کارکنان، هزینه‌ها و رضایت مشتری را در شیفت‌های سرویس هماهنگ کن.",
  "sim.chocolate-factory.title": "کارخانه شکلات",
  "sim.chocolate-factory.desc": "یک کارخانه شیرینی‌سازی را اداره کن — تأمین کاکائو، برنامه‌ریزی تولید و کنترل کیفیت.",
  "sim.solar-energy.title": "نیروگاه انرژی خورشیدی",
  "sim.solar-energy.desc": "یک نصب خورشیدی را طراحی و راه‌اندازی کن — اندازه‌گیری پنل‌ها، مدیریت صادرات به شبکه و ردیابی بازگشت سرمایه.",
  "sim.hvac-systems.title": "سیستم‌های HVAC",
  "sim.hvac-systems.desc": "سیستم‌های گرمایش، تهویه و سرمایش (تهویه مطبوع) را برای ساختمان‌های تجاری نصب و نگهداری کن.",
  "sim.logistics-supply.title": "لجستیک و زنجیره تأمین",
  "sim.logistics-supply.desc": "عملیات انبار، مسیر ناوگان و روابط با تأمین‌کنندگان را بهینه کن تا به KPIهای تحویل برسـی.",
  "sim.barber-salon.title": "سالن آرایشگاه مردانه",
  "sim.barber-salon.desc": "یک آرایشگاه مردانه را مدیریت کن: نوبت‌ها، برنامه کارکنان، قیمت‌گذاری و استراتژی‌های حفظ مشتری.",
  "sim.board-surgeon.title": "جراح تخته‌ای",
  "sim.board-surgeon.desc": "تصمیم‌گیری جراحی با ریسک بالا را در یک سالن عمل شبیه‌سازی‌شده انجام بده — مدیریت زمان و ایمنی بیمار.",
  "sim.english-journey.title": "سفر انگلیسی",
  "sim.english-journey.desc": "آموزش‌دهندگان را از طریق یک برنامه ساختارمند زبان انگلیسی هدایت کن و با سطوح مختلف مهارت سازگار کن.",
  "sim.music-training.title": "استودیوی آموزش موسیقی",
  "sim.music-training.desc": "یک مدرسه موسیقی را اداره کن: زمان‌بندی کلاس‌ها، مدیریت سازها و پیگیری پیشرفت دانش‌آموزان تا زمان اجراهای نمایشی.",
  "sim.trade-tycoon.title": "تاجر حرفه‌ای",
  "sim.trade-tycoon.desc": "یک امپراتوری معاملاتی بساز — ارزان بخر، گران بفروش، و موجودی و جریان نقدی را در بازارهای متعدد مدیریت کن.",
  "sim.vehicle-diagnostics.title": "شبیه‌ساز عیب‌یابی و تعمیر خودرو",
  "sim.vehicle-diagnostics.desc": "کدهای خطای OBD-II را عیب‌یابی کن، خرابی‌های الکتریکی را ردیابی کن و یک روند واقعی تعمیر خودرو را مدیریت کن.",
  "sim.marine-vessel.title": "ردیابی شناورهای دریایی و لجستیک دریایی",
  "sim.marine-vessel.desc": "یک ناوگان جهانی را فرماندهی کن — شناورها را ردیابی کن، ازدحام بندر، شرایط اضطراری آب‌وهوایی و تأخیرهای کانال را مدیریت کن.",
