  "social.error.not_connected": "این حساب هیچ مجوز فعالی ندارد. پیش از فعال‌سازی آن را متصل کنید.",
  "social.error.threads_refresh_failed": "توکن Threads تمدید نشد. بعداً دوباره تلاش کنید یا حساب را دوباره متصل کنید.",
  "legal.privacy.collect.messaging.heading": "پیام‌های فیسبوک مسنجر و اینستاگرام دایرکت",
  "legal.privacy.collect.messaging.text": "وقتی در فیسبوک مسنجر یا اینستاگرام دایرکت به صفحه یا حساب Visionex پیام می‌دهید، متا متن نوشته‌شده، شناسهٔ محدود خودش برای شما (شناسه‌ای وابسته به صفحه یا حساب اینستاگرام — نه نمایه، ایمیل یا شمارهٔ تلفن شما)، شناسهٔ پیام و زمان ارسال را برای ما می‌فرستد. ما این‌ها را نگه می‌داریم تا پرسش شما را بخوانیم، ترتیب گفت‌وگو را حفظ کنیم، به یک پیام دو بار پاسخ ندهیم و هرگاه کمک خودکار کافی نبود آن را به یک نفر بسپاریم. متن پیام شما برای تولید پاسخ توسط ارائه‌دهندگان هوش مصنوعی ثالث پردازش می‌شود. ما هرگز رمز عبور فیسبوک یا اینستاگرام، فهرست دوستان یا دنبال‌کنندگان، و جزئیات نمایهٔ شما را دریافت نمی‌کنیم.",
  "legal.privacy.third.meta.name": "Meta Platforms (فیسبوک مسنجر، اینستاگرام دایرکت، واتساپ)",
  "legal.privacy.third.meta.purpose": "پیام‌هایی را که از طریق مسنجر، اینستاگرام دایرکت یا واتساپ به Visionex می‌فرستید تحویل می‌دهد و پاسخ‌های ما را به شما می‌رساند. متا این پیام‌ها را در سکوهای خودش و بر پایهٔ شرایط و سیاست حریم خصوصی خودش مدیریت می‌کند.",
  "legal.privacy.deletionLink": "برای درخواست حذف داده‌هایی که از فیسبوک مسنجر یا اینستاگرام دایرکت دریافت کرده‌ایم، دستورالعمل این صفحه را دنبال کنید:",
  "legal.dataDeletion.title": "درخواست حذف داده‌ها",
  "legal.dataDeletion.intro": "این صفحه توضیح می‌دهد چگونه حذف داده‌هایی را که Visionex دربارهٔ شما نگه می‌دارد درخواست کنید، از جمله آنچه هنگام پیام دادن در فیسبوک مسنجر یا اینستاگرام دایرکت از متا دریافت کرده‌ایم.",
  "legal.dataDeletion.howTitle": "چگونه حذف را درخواست کنید",
  "legal.dataDeletion.step1": "برای ما ایمیلی با موضوع «درخواست حذف داده‌ها» بفرستید.",
  "legal.dataDeletion.step2": "بگویید داده‌ها به کدام سرویس مربوط است — برای نمونه پیامی که در فیسبوک مسنجر یا اینستاگرام دایرکت به صفحهٔ Visionex فرستاده‌اید — و تقریباً چه زمانی با ما تماس گرفته‌اید، تا بتوانیم گفت‌وگوی درست را بیابیم. اگر حساب Visionex دارید، درخواست را از نشانی ایمیل همان حساب بفرستید.",
  "legal.dataDeletion.step3": "دریافت درخواست را تأیید می‌کنیم، آنچه را نگه داشته‌ایم حذف می‌کنیم و سپس در پاسخ به شما می‌نویسیم چه چیزی حذف شد.",
  "legal.dataDeletion.contact": "درخواست‌ها را به این نشانی بفرستید:",
  "legal.dataDeletion.whatTitle": "چه چیزی حذف می‌شود",
